/// <summary>
/// Extension class for VendInvoiceTrans table to include custom logic for initializing
/// extended comment fields from VendInvoiceInfoLine.
/// </summary>
[ExtensionOf(tableStr(VendInvoiceTrans))]
final class METVendInvoiceTrans_Extension
{

}

Method.Source:
/// <summary>
/// Initializes the VendInvoiceTrans record with extended comment data from the VendInvoiceInfoLine parameter.
/// If MetExtCommentQty is provided, it takes precedence; otherwise, MetExtComment is used.
/// </summary>
/// <param name="_vendInvoiceInfoLine">The VendInvoiceInfoLine record containing extended comment information.</param>
void initFromVendInvoiceInfoLine(VendInvoiceInfoLine _vendInvoiceInfoLine)
{
    next initFromVendInvoiceInfoLine(_vendInvoiceInfoLine);

    RefRecId refId = _vendInvoiceInfoLine.ReasonTableRef ?  _vendInvoiceInfoLine.ReasonTableRef: _vendInvoiceInfoLine.MetPriceVarianceReasonCode;

    ReasonTable reasonTable = ReasonTable::find(ReasonTableRef::find(refId).Reason);
    boolean qtyFailure = reasonTable.METVarianceType == METVarianceType::QuantityVarianceOver
                      || reasonTable.METVarianceType == METVarianceType::QuantityVarianceUnder
                      || reasonTable.METVarianceType == METVarianceType::QuantityVarianceNoDelivery;

    this.MetExtComment = qtyFailure ? _vendInvoiceInfoLine.MetExtCommentQty : _vendInvoiceInfoLine.MetExtComment;
    this.ReasonTableRef = qtyFailure ? _vendInvoiceInfoLine.ReasonTableRef : _vendInvoiceInfoLine.MetPriceVarianceReasonCode;
}
